This PR adds a new CLI option `--indirect` which if passed, activates any usages of the new `[indirect]` attribute on SRG Semantic declarations. Here's a code snippet to illustrate the behavior:

```hlsl
[indirect]
ShaderResourceGroupSemantic BindingPerObject
{
    FrequencyId = 0;
};

[indirect]
ShaderResourceGroupSemantic BindingPerMaterial
{
    FrequencyId = 1;
};

ShaderResourceGroup PerObject : BindingPerObject
{
    row_major float3x4 m_modelToWorld;
}

ShaderResourceGroup MaterialSrg : BindingPerMaterial
{
    float3 m_baseColor;
    float m_baseColorFactor;

    Texture2D m_baseColorMap;

    Sampler m_sampler
    {
       AddressU = Clamp;
       AddressV = Clamp;
       MinFilter = Linear;
       MagFilter = Linear;
       MipFilter = Linear;
    };
}

float4 MainPS(float2 uv : TEXCOORD) : SV_Target0
{
    float4 baseColorMapSample = MaterialSrg::m_baseColorMap.Sample(MaterialSrg::m_sampler, uv);
    float3 baseColor = baseColorMapSample.rgb * MaterialSrg::m_baseColor.rgb * MaterialSrg::m_baseColorFactor;

    return float4(baseColor, 1.0);
}
```

The SRG semantics above have `[indirect]` attributes, indicating that the shader author would like all UAV/SRV descriptors including the implicit struct to be accessed through a layer of indirection (to support ray tracing or indirect/instanced draws). After compiling the above with the flags `--use-spaces --indirect --entry-points=MainPS`, `azslc` will emit the following shader:

```hlsl

ByteAddressBuffer ManagedHeap_ByteAddressBuffer[] : register(t0, space100);
Texture2D ManagedHeap_Texture2D[] : register(t0, space101);
Texture3D ManagedHeap_Texture3D[] : register(t0, space102);
TextureCube ManagedHeap_TextureCube[] : register(t0, space103);
SamplerState ManagedHeap_SamplerState[] : register(s0, space104);
struct ManagedIndirection { uint index; uint offset; };

/* Generated code from  ShaderResourceGroup PerObject*/
struct PerObject_SRGConstantsStruct
{
    row_major float3x4 PerObject_m_modelToWorld;
};

ConstantBuffer<ManagedIndirection> PerObject_indirect : register(b0, space0);
static uint PerObject_base;
void setPerObject_base(uint instanceId) {
        PerObject_base = 8 * instanceId + PerObject_indirect.offset;
}

static ::PerObject_SRGConstantsStruct PerObject_SRGConstantBuffer;
void setPerObject_SRGConstantBuffer() {
        uint2 indexOffset = ManagedHeap_ByteAddressBuffer[PerObject_indirect.index].Load<uint2>(PerObject_base);
        PerObject_SRGConstantBuffer = ManagedHeap_ByteAddressBuffer[indexOffset.x].Load<::PerObject_SRGConstantsStruct>(indexOffset.y);
}

/* Generated code from  ShaderResourceGroup MaterialSrg*/
struct MaterialSrg_SRGConstantsStruct
{
     float3 MaterialSrg_m_baseColor;
     float MaterialSrg_m_baseColorFactor;
};

ConstantBuffer<ManagedIndirection> MaterialSrg_indirect : register(b0, space1);
static uint MaterialSrg_base;
void setMaterialSrg_base(uint instanceId) {
        MaterialSrg_base = 16 * instanceId + MaterialSrg_indirect.offset;
}

static ::MaterialSrg_SRGConstantsStruct MaterialSrg_SRGConstantBuffer;
void setMaterialSrg_SRGConstantBuffer() {
        uint2 indexOffset = ManagedHeap_ByteAddressBuffer[MaterialSrg_indirect.index].Load<uint2>(MaterialSrg_base);
        MaterialSrg_SRGConstantBuffer = ManagedHeap_ByteAddressBuffer[indexOffset.x].Load<::MaterialSrg_SRGConstantsStruct>(indexOffset.y);
}

static Texture2D MaterialSrg_m_baseColorMap;
void setMaterialSrg_m_baseColorMap() {
        MaterialSrg_m_baseColorMap = ManagedHeap_Texture2D[ManagedHeap_ByteAddressBuffer[MaterialSrg_indirect.index].Load<uint>(MaterialSrg_base + 8)];
}
static SamplerState MaterialSrg_m_sampler;
void setMaterialSrg_m_sampler() {
        MaterialSrg_m_sampler = ManagedHeap_SamplerState[ManagedHeap_ByteAddressBuffer[MaterialSrg_indirect.index].Load<uint>(MaterialSrg_base + 12)];
}

float4 MainPS(  float2 uv :TEXCOORD, uint instanceId :SV_InstanceID) :SV_Target0{
setPerObject_base(instanceId);
setPerObject_SRGConstantBuffer();
setMaterialSrg_base(instanceId);
setMaterialSrg_SRGConstantBuffer();
setMaterialSrg_m_baseColorMap();
setMaterialSrg_m_sampler();
float4 baseColorMapSample = ::MaterialSrg_m_baseColorMap . Sample ( ::MaterialSrg_m_sampler , uv ) ;
float3 baseColor = baseColorMapSample . rgb * ::MaterialSrg_SRGConstantBuffer.MaterialSrg_m_baseColor . rgb * ::MaterialSrg_SRGConstantBuffer.MaterialSrg_m_baseColorFactor ;
return float4 ( baseColor , 1.0 ) ;
}
```

Note the addition of the instance id, as well as setters which are invoked for every SRV/UAV. The stride and offsets are computed statically based on how many SRV/UAVs are present in an SRG, and are also reflected in the SRG and root signature. Note also that the new `--entry-points` CLI option is needed to emit the setters at the start of each entry point function. Another option would be to emit a getter per SRV/UAV, however, this generates significantly more bytecode, and may not always be optimized by the compiler.

## BOJ 13558 G2 등차수열의 개수
- 수학
- 조합론
- gold2

<br>


### 🔍 문제 설명
https://www.acmicpc.net/problem/13558

길이가 N인 수열 A1, A2, ..., AN이 주어진다. 이때, 1 ≤ i < j < k ≤ N 이면서, Aj - Ai = Ak - Aj를 만족하는 (i, j, k) 쌍의 개수를 구하는 프로그램을 작성하시오.


#### 입력
첫째 줄에 수열의 크기 N (3 ≤ N ≤ 100,000)가 주어진다.

둘째 줄에는 A1, A2, ..., AN이 주어진다. (1 ≤ Ai ≤ 30,000)

#### 출력
1 ≤ i < j < k ≤ N 이면서, Aj - Ai = Ak - Aj를 만족하는 (i, j, k) 쌍의 개수를 출력한다.

###  💡 풀이

3개의 숫자중 중산 숫자를 중심으로 좌측에 있는 각 숫자의 카운트를 저장하는 배열 `leftNumbers`, 우측에 있는 숫자의 카운트를 저장하는 배열 `rightNumbers`를 사용하여 풀었다.

중간 숫자를 중심으로 좌,우로 차이가 같은 두 숫자의 갯수를 곱한 값을 `count`에 더해주도 모든 수열에 대해서 같은 계산을 반복한다

```java
		for (int i = 2; i <= N-1; i++) {
			leftNumbers[arr[i-1]]++;
			rightNumbers[arr[i]]--;
			
			count += leftNumbers[arr[i]]*rightNumbers[arr[i]];
			
			for (int j = 1; (j <= arr[i]-1) && (arr[i] + j <= max); j++) {
				//중간 숫자를 기준으로 좌,우 차이가 같은 수 카운트의 곱만큼 더함
				count += leftNumbers[arr[i] - j]*rightNumbers[arr[i] + j];
				count += leftNumbers[arr[i] + j]*rightNumbers[arr[i] - j];
			}
		}
```



<br><br>

###  💡 소스코드
```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class BOJ_13558_G2_등차수열의개수 {
	static int N, max;
	static long count;
	static int[] arr;
	static long[] rightNumbers, leftNumbers;

	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		
		N = Integer.parseInt(br.readLine());
		
		arr = new int[N+1];
		//기준 숫자 우측에 있는 수 카운트
		rightNumbers = new long[30001];
		//기준 숫자 좌측에 있는 수 카운트
		leftNumbers = new long[30001];
		
		StringTokenizer st = new StringTokenizer(br.readLine());
		
		for (int i = 1; i <= N; i++) {
			arr[i] = Integer.parseInt(st.nextToken());
			max = Math.max(max, arr[i]);
			rightNumbers[arr[i]]++;
		}
		
		rightNumbers[arr[1]]--;
		
		//중간 숫자 수만큼 반복
		for (int i = 2; i <= N-1; i++) {
			leftNumbers[arr[i-1]]++;
			rightNumbers[arr[i]]--;
			
			count += leftNumbers[arr[i]]*rightNumbers[arr[i]];
			
			for (int j = 1; (j <= arr[i]-1) && (arr[i] + j <= max); j++) {
				//중간 숫자를 기준으로 좌,우 차이가 같은 수 카운트의 곱만큼 더함
				count += leftNumbers[arr[i] - j]*rightNumbers[arr[i] + j];
				count += leftNumbers[arr[i] + j]*rightNumbers[arr[i] - j];
			}
		}
		
		System.out.println(count);
	}
}





```


