This PR is that solving duplicate namespace issues, like https://github.com/Azure/azure-functions-openapi-extension/issues/248

I added `NamespaceType` option in `IOpenApiConfigurationOptions`.

```cs
public interface IOpenApiConfigurationOptions
{
    ...
    /// <summary>
    /// Gets or sets the type of object name.
    /// </summary>
    OpenApiNamespaceType NamespaceType { get; set; }
}
```

The `OpenApiNamespaceType` have a two value, `ShortName` and `FullName`.
The `ShortName` is the `default` value in this type and it's showing the same result currently.
If `FullName` is set, the model name will be generated that has a full path, Like the below.

```json
{
  ...
  "paths": {
    "/post-applicationjson-string": {
      "post": {
        ...
        "responses": {
          "200": {
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/microsoft.Azure.WebJobs.Extensions.OpenApi.TestApp.Models.StringObjectModel"
                }
              }
            }
          }
        }
      }
    }
  },
  "components": {
    "schemas": {
      ...
      "microsoft.Azure.WebJobs.Extensions.OpenApi.TestApp.Models.GenericAndRecursiveObjectModel": {
        "type": "object",
        "properties": {
          "listValue": {
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/microsoft.Azure.WebJobs.Extensions.OpenApi.TestApp.Models.GenericAndRecursiveObjectModel"
            }
          }
        }
      },
      "microsoft.Azure.WebJobs.Extensions.OpenApi.TestApp.Models.StringObjectModel": {
        "type": "object",
        "properties": {
          "stringValue": {
            "type": "string"
          }
        }
      },
      "system.Exception": {
        "type": "object"
      },
      "system.InvalidOperationException": {
        "type": "object"
      },
      "system.List_string": {
        "type": "array",
        "items": {
          "type": "string"
        }
      }
    }
  }
}
```

